const loteItems = $input.all().map(item => item.json);

// Funciones auxiliares
const escape = (v) => String(v).replace(/'/g, "''");

const formatTimestamp = (fechaStr) => {
  if (!fechaStr || typeof fechaStr !== 'string' || fechaStr.trim() === '') return 'NULL';
  const partes = fechaStr.split(' ');
  const fecha = partes[0];
  const hora = partes[1] || '00:00:00';
  const [d, m, a] = fecha.split('/');
  if (!d || !m || !a) return 'NULL';
  return `'${a}-${m.padStart(2, '0')}-${d.padStart(2, '0')} ${hora}'`;
};

const parseInteger = (val) => {
  if (val === undefined || val === null || val === '') return '0';
  const num = parseInt(val, 10);
  return isNaN(num) ? '0' : num;
};

const values = loteItems.map(item => {
  const legacyId = escape(item.ID_Cliente || '');
  const creador = item.Creador_Cliente ? `'${escape(item.Creador_Cliente)}'` : 'NULL';
  const creadoEn = formatTimestamp(item.Creado_Cliente);
  const modificador = item.Modificador_Cliente ? `'${escape(item.Modificador_Cliente)}'` : 'NULL';
  const modificadoEn = formatTimestamp(item.Modificado_Cliente);
  const identificacion = item.Identificacion_Cliente ? `'${escape(item.Identificacion_Cliente)}'` : 'NULL';
  const tipoId = item.TipoID_Cliente ? `'${escape(item.TipoID_Cliente)}'` : 'NULL';
  const nombre = item.Nombre_Cliente ? `'${escape(item.Nombre_Cliente)}'` : 'NULL';
  const ciudad = item.Ciudad_Cliente ? `'${escape(item.Ciudad_Cliente)}'` : 'NULL';
  const direccion = item.Direccion_Cliente ? `'${escape(item.Direccion_Cliente)}'` : 'NULL';
  const mostrarContacto = item.shwContacto_Cliente ? `'${escape(item.shwContacto_Cliente)}'` : 'NULL';
  const contacto = item.Contacto_Cliente ? `'${escape(item.Contacto_Cliente)}'` : 'NULL';
  const telefono = item.TelefonoContacto_Cliente !== undefined && item.TelefonoContacto_Cliente !== null ? `'${escape(String(item.TelefonoContacto_Cliente))}'` : 'NULL';
  const email = item.Email_Cliente ? `'${escape(item.Email_Cliente)}'` : 'NULL';
  const version = parseInteger(item.Update_Cliente);

  return `('${legacyId}', ${creador}, ${creadoEn}, ${modificador}, ${modificadoEn}, ${identificacion}, ${tipoId}, ${nombre}, ${ciudad}, ${direccion}, ${mostrarContacto}, ${contacto}, ${telefono}, ${email}, ${version})`;
}).join(', ');

if (!values) {
  return [{ json: { sql: '', status: 'sin_datos' } }];
}

const sql = `INSERT INTO public.clientes 
  (legacy_id, creador, creado_en, modificador, modificado_en, identificacion, tipo_identificacion, nombre, ciudad, direccion, mostrar_contacto, contacto, telefono_contacto, email, version)
VALUES ${values}
ON CONFLICT (legacy_id) DO UPDATE SET
  creador = EXCLUDED.creador,
  creado_en = EXCLUDED.creado_en,
  modificador = EXCLUDED.modificador,
  modificado_en = EXCLUDED.modificado_en,
  identificacion = EXCLUDED.identificacion,
  tipo_identificacion = EXCLUDED.tipo_identificacion,
  nombre = EXCLUDED.nombre,
  ciudad = EXCLUDED.ciudad,
  direccion = EXCLUDED.direccion,
  mostrar_contacto = EXCLUDED.mostrar_contacto,
  contacto = EXCLUDED.contacto,
  telefono_contacto = EXCLUDED.telefono_contacto,
  email = EXCLUDED.email,
  version = EXCLUDED.version;`;

return [{ json: { sql } }];
